import { fraction, type FractionValue } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, LocalizedText, PracticeItem } from '../../features/unit-v2/types.ts'

/* ==========================================================================
   Zenbaki errealak · Batxilergoa 1 · Gizarte Zientziak — diagnostic, guided
   practice, exercise bank and challenges, with the scope of unit 1 of Anaya
   Matemáticas aplicadas a las Ciencias Sociales I (all the exercises,
   contexts and numbers are our own). Many use social and economic data:
   votes, budgets, prices, salaries, population. Every closed answer is a
   single number or a fraction: when the result is an interval, a set or a
   radical, the question asks for one of its numbers.
   ========================================================================== */

/** Arabic writes the decimal point instead of the comma, so {,} becomes . there */
const say = (eu: string, es: string, ar: string, en: string): LocalizedText => ({ eu, es, en, ar: ar.replace(/\{,\}/g, '.') })
/** Same formula everywhere, decimal point in Arabic */
const same = (value: string): LocalizedText => ({ eu: value, es: value, en: value, ar: value.replace(/\{,\}/g, '.') })
/** A decimal written with the comma, as an exact fraction */
const v = (text: string): FractionValue => {
    const negative = text.startsWith('-')
    const [whole, decimals = ''] = text.replace('-', '').split(',')
    return fraction((negative ? -1 : 1) * Number(whole + decimals), 10 ** decimals.length)
}
const n = (value: number) => fraction(value)
const f = (numerator: number, denominator: number) => fraction(numerator, denominator)

const HUNDREDTHS = say('Hurbildu ehunenetara.', 'Aproxima a las centésimas.', 'قرّب إلى الأجزاء من مئة.', 'Round to two decimal places.')
const TENTHS = say('Hurbildu hamarrenetara.', 'Aproxima a las décimas.', 'قرّب إلى الأجزاء من عشرة.', 'Round to one decimal place.')
const AS_FRACTION = say('Eman zatiki gisa.', 'Dalo como fracción.', 'اكتبه كسرًا.', 'Give it as a fraction.')
/** A prompt followed by an instruction (rounding, fraction) */
const with_ = (prompt: LocalizedText, ...rules: LocalizedText[]): LocalizedText => ({
    eu: [prompt.eu, ...rules.map((rule) => rule.eu)].join(' '),
    es: [prompt.es, ...rules.map((rule) => rule.es)].join(' '),
    en: [prompt.en, ...rules.map((rule) => rule.en)].join(' '),
    ar: [prompt.ar, ...rules.map((rule) => rule.ar)].join(' ')
})
/** «Formula. How much is a?» in the four languages */
const howMuch = (formula: string, letter = 'a') => say(`${formula}. Zenbat da $${letter}$?`, `${formula}. ¿Cuánto vale $${letter}$?`, `${formula}. كم تساوي $${letter}$؟`, `${formula}. What is the value of $${letter}$?`)
const calc = (formula: string) => say(`Kalkulatu ${formula}.`, `Calcula ${formula}.`, `احسب ${formula}.`, `Work out ${formula}.`)
/** «How many elements does the set have?» */
const howMany = (set: string) => say(`Zenbat elementu ditu ${set} multzoak?`, `¿Cuántos elementos tiene ${set}?`, `كم عنصرًا في ${set}؟`, `How many elements does ${set} have?`)
/** «What is the whole-number part of the logarithm?» */
const wholePart = (log: string) => say(`Zein da ${log} logaritmoaren zati osoa?`, `¿Cuál es la parte entera de ${log}?`, `ما الجزء الصحيح من ${log}؟`, `What is the whole-number part of ${log}?`)

